class ArcadeTextIdentityDouble
{
 var $rows=array();var $queries=array();var $opened=0;var $fail=false;
 function sql_escape($s){return addslashes($s);}
 function sql_query($s){$this->queries[]=$s;if($this->fail){return false;}$this->opened++;return true;}
 function sql_fetchrowset($r){return $this->rows;}
 function sql_freeresult($r){$this->opened--;}
}
$db=new ArcadeTextIdentityDouble();foreach(array('0','A&B',"O'Reilly",'Grüße 😀','&#39;')as$raw){foreach(array(ENT_QUOTES,ENT_COMPAT)as$flags){$key=phpbb_username_key($raw,$flags);as_check($key!=='','Valid identity fixture');$db->rows=array(array('user_id'=>7,'username'=>$key));as_check(ax_moderator($raw)===7&&$db->opened===0,'Actual category resolver retains exact full account identity including0');as_check(strpos(end($db->queries),$db->sql_escape($key))!==false,'Lookup includes real historical HTML key');$moderator=$key;$source=$ax_sources['cats'];as_check(preg_match('/"MODERATOR" => ([^\r\n]*),/',$source,$m)===1,'Actual category form value');$value=eval('return '.$m[1].';');as_check(html_entity_decode($value,ENT_QUOTES,'UTF-8')===$raw,'Moderator form shows raw name exactly once');$count++;}}
