$db->queries=array();as_check(ax_moderator('')===0&&!$db->queries,'Explicit blank still removes moderator');$db->rows=array(array('user_id'=>7,'username'=>'Existing'));$caught=false;try{ax_moderator(str_repeat('x',26));}catch(ArcadeSummaryExit$e){$caught=true;}as_check($caught&&!$db->queries,'Overlength identity never resolves a25-character prefix');$count+=2;
